// GitHub Activity section — loads data/github-activity.json (generated by
// a GitHub Actions workflow + Python script) and renders it into the
// #github-activity section. No token, no auth calls made from the browser.

(function () {
  const DATA_URL = "data/github-activity.json";

  function timeAgo(isoString) {
    if (!isoString) return "";
    const then = new Date(isoString).getTime();
    const diffSeconds = Math.floor((Date.now() - then) / 1000);
    const units = [
      ["year", 31536000],
      ["month", 2592000],
      ["day", 86400],
      ["hour", 3600],
      ["minute", 60],
    ];
    for (const [label, secs] of units) {
      const val = Math.floor(diffSeconds / secs);
      if (val >= 1) return `${val} ${label}${val > 1 ? "s" : ""} ago`;
    }
    return "just now";
  }

  function renderCurrentlyWorkingOn(items) {
    if (!items || !items.length) return "";
    const cards = items
      .map(
        (item) => `
          <div class="gh-working-card">
            <span class="gh-working-emoji">${item.emoji || "🔧"}</span>
            <div>
              <strong>${item.repo}</strong>
              <span class="gh-working-note">${item.note}</span>
            </div>
          </div>`
      )
      .join("");
    return `<div class="gh-working-grid">${cards}</div>`;
  }

  function renderHeatmap(heatmap) {
    const days = Object.keys(heatmap || {}).slice(-371); // ~53 weeks, matches GitHub's own graph
    if (!days.length) {
      return `<p class="gh-empty">No recent public activity to show yet.</p>`;
    }
    const max = Math.max(...days.map((d) => heatmap[d]), 1);
    const cells = days
      .map((day) => {
        const count = heatmap[day];
        const intensity = count === 0 ? 0 : Math.ceil((count / max) * 4);
        return `<span class="gh-cell gh-cell-${intensity}" title="${day}: ${count} event${count === 1 ? "" : "s"}"></span>`;
      })
      .join("");
    return `<div class="gh-heatmap">${cells}</div>`;
  }

  function renderRecentCommits(commits) {
    if (!commits || !commits.length) {
      return `<p class="gh-empty">No recent commits found.</p>`;
    }
    const items = commits
      .map(
        (c) => `
        <li class="gh-commit">
          <span class="gh-commit-repo">${c.repo.split("/")[1] || c.repo}</span>
          <span class="gh-commit-msg">${escapeHtml(c.message)}</span>
          <span class="gh-commit-time">${timeAgo(c.date)}</span>
        </li>`
      )
      .join("");
    return `<ul class="gh-commit-list">${items}</ul>`;
  }

  function renderRepos(repos) {
    if (!repos || !repos.length) {
      return `<p class="gh-empty">No repositories found.</p>`;
    }
    const cards = repos
      .map(
        (r) => `
        <a class="gh-repo-card" href="${r.url}" target="_blank" rel="noopener">
          <h5>${r.name}</h5>
          <p>${escapeHtml(r.description || "No description provided.")}</p>
          <div class="gh-repo-meta">
            ${r.language ? `<span class="gh-lang-dot"></span>${r.language}` : ""}
            <span>Updated ${timeAgo(r.pushed_at)}</span>
          </div>
        </a>`
      )
      .join("");
    return `<div class="gh-repo-grid">${cards}</div>`;
  }

  function renderLanguages(languages) {
    if (!languages || !languages.length) return "";
    const bars = languages
      .slice(0, 6)
      .map(
        (l) => `
        <div class="gh-lang-row">
          <span class="gh-lang-name">${l.language}</span>
          <div class="gh-lang-bar-track">
            <div class="gh-lang-bar-fill" style="width:${l.percent}%"></div>
          </div>
          <span class="gh-lang-percent">${l.percent}%</span>
        </div>`
      )
      .join("");
    return `<div class="gh-lang-list">${bars}</div>`;
  }

  function escapeHtml(str) {
    const div = document.createElement("div");
    div.textContent = str;
    return div.innerHTML;
  }

  async function init() {
    const section = document.getElementById("github-activity");
    if (!section) return;

    try {
      const res = await fetch(DATA_URL, { cache: "no-store" });
      if (!res.ok) throw new Error(`Status ${res.status}`);
      const data = await res.json();

      const workingEl = section.querySelector("#gh-working-on");
      const heatmapEl = section.querySelector("#gh-heatmap");
      const commitsEl = section.querySelector("#gh-recent-commits");
      const reposEl = section.querySelector("#gh-recent-repos");
      const langEl = section.querySelector("#gh-languages");
      const updatedEl = section.querySelector("#gh-last-updated");

      if (workingEl) workingEl.innerHTML = renderCurrentlyWorkingOn(data.currently_working_on);
      if (heatmapEl) heatmapEl.innerHTML = renderHeatmap(data.heatmap);
      if (commitsEl) commitsEl.innerHTML = renderRecentCommits(data.recent_commits);
      if (reposEl) reposEl.innerHTML = renderRepos(data.recently_updated_repos);
      if (langEl) langEl.innerHTML = renderLanguages(data.languages);
      if (updatedEl && data.generated_at) {
        updatedEl.textContent = `Last synced ${timeAgo(data.generated_at)}`;
      }
    } catch (err) {
      console.warn("Could not load GitHub activity data:", err);
      section.querySelector(".gh-activity-body").innerHTML =
        `<p class="gh-empty">GitHub activity couldn't be loaded right now. Check back soon!</p>`;
    }
  }

  document.addEventListener("DOMContentLoaded", init);
})();